#!/usr/bin/env python3
"""
generate_proof_completeness.py — Sprint 5 task #7 orchestrator.
===============================================================

Reads ``AutoGenerated/parameters.json`` (the canonical registry export),
runs :class:`metaphysica.simulations.PM.analysis.proof_completeness.ProofLedger`
across every parameter, and writes two artefacts:

* ``AutoGenerated/proof_completeness_ledger.json``  — full ledger payload
  (rows, status_counts, per_section matrix, uncertainties, meta).
* ``AutoGenerated/proof_completeness_ledger.md``    — grouped Markdown
  table with the columns mandated by the task plan
  (``Parameter | Value | Status | EML Tree | Uncertainty``), grouped
  by section.

Both files are regenerated unconditionally; no manual editing should
ever land in them.

Usage
-----
``python -m metaphysica.generators.generate_proof_completeness``

The build system (``build.py``) wires this in as a post-pipeline step
so the JSON+MD outputs are always in sync with the registry that was
just written by ``run_all_simulations``.

Copyright (c) 2025-2026 Andrew Keith Watts. All rights reserved.
"""
from __future__ import annotations

import json
import math
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Mapping

from metaphysica.generators._common import autogen_dir

try:
    from metaphysica.simulations.PM.analysis.proof_completeness import (
        STATUS_ORDER,
        ProofLedger,
    )
except ModuleNotFoundError as _exc:
    if "pandas" not in str(_exc):
        raise
    print(
        "  proof_completeness ledger skipped: pandas not installed "
        "(install with pip install metaphysica[plots])"
    )
    sys.exit(0)


PARAMETERS_FILENAME = "parameters.json"
LEDGER_JSON_NAME    = "proof_completeness_ledger.json"
LEDGER_MD_NAME      = "proof_completeness_ledger.md"


# Pretty-print labels for the five status buckets (markdown uses these,
# JSON sticks with the snake_case STATUS_* constants).
STATUS_PRETTY: Dict[str, str] = {
    "fully_derived":         "Fully EML-derived",
    "numerical_agreement":   "Numerical agreement",
    "experimental_anchor":   "Experimental anchor (NuFIT / PDG / CODATA / DESI / Planck)",
    "fitted":                "Still fitted (legacy marker)",
    "open_tension":          "Open tension",
    "eml_deferred":          "EML deferred (speculative Orch-OR / Gnosis)",
}


def _load_registry_from_parameters_json() -> Dict[str, Mapping[str, Any]]:
    """Load the parameters.json export and return the inner ``parameters`` dict.

    Falls back gracefully to an empty dict if the file doesn't exist yet
    (e.g. orchestrator invoked before ``run_all_simulations``) — the
    downstream ledger still writes a (mostly-empty) JSON/MD pair so the
    website doesn't 404.
    """
    p = autogen_dir() / PARAMETERS_FILENAME
    if not p.exists():
        return {}
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}
    if isinstance(data, Mapping) and isinstance(data.get("parameters"), Mapping):
        return dict(data["parameters"])
    if isinstance(data, Mapping):
        return dict(data)
    return {}


def _fmt_value(v: Any) -> str:
    """Format a registry value for markdown table display."""
    if v is None:
        return "—"
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, (int,)):
        return str(v)
    if isinstance(v, float):
        if not math.isfinite(v):
            return "—"
        absv = abs(v)
        if absv == 0.0:
            return "0"
        if absv < 1e-3 or absv >= 1e6:
            return f"{v:.6e}"
        return f"{v:.6g}"
    s = str(v)
    if len(s) > 80:
        s = s[:77] + "..."
    # Escape pipes so markdown table rows stay well-formed.
    return s.replace("|", "\\|")


def _fmt_uncertainty(u: Any) -> str:
    """Format the Bayesian uncertainty cell."""
    try:
        x = float(u)
    except (TypeError, ValueError):
        return "0"
    if not math.isfinite(x) or x == 0.0:
        return "0"
    if abs(x) < 1e-3 or abs(x) >= 1e6:
        return f"{x:.3e}"
    return f"{x:.3g}"


def _fmt_eml(tree: Any) -> str:
    """Format the EML tree cell — collapse 'None'/'' to em-dash."""
    if tree is None:
        return "—"
    s = str(tree)
    if s in {"", "None"}:
        return "—"
    if len(s) > 80:
        s = s[:77] + "..."
    return s.replace("|", "\\|")


def _fmt_duplicates(duplicates: Any) -> str:
    """Format the Duplicate_Derivations cell.

    Surfaces the alternate parameter IDs that derive the same observable
    (per the shared :data:`OBSERVABLE_GROUPS` map) so reviewers can spot
    cross-checks at a glance. Empty lists render as an em-dash.
    """
    if duplicates is None:
        return "—"
    try:
        items = [str(d) for d in list(duplicates)]
    except TypeError:
        return "—"
    items = [s for s in items if s]
    if not items:
        return "—"
    # Wrap each ID in backticks for readability + escape pipes so the
    # markdown table stays well-formed.
    rendered = ", ".join(f"`{s}`".replace("|", "\\|") for s in items)
    if len(rendered) > 200:
        rendered = rendered[:197] + "..."
    return rendered


def _render_markdown(ledger: Dict[str, Any], *, timestamp: str) -> str:
    """Render the ledger payload as a section-grouped markdown table."""
    rows: List[Dict[str, Any]] = list(ledger.get("rows", []))
    status_counts: Dict[str, int] = dict(ledger.get("status_counts", {}))
    per_section: Dict[str, Dict[str, int]] = dict(ledger.get("per_section", {}))
    meta = dict(ledger.get("meta", {}))

    out: List[str] = []
    out.append("# Proof Completeness Ledger")
    out.append("")
    out.append(
        f"_Auto-generated by `metaphysica.generators.generate_proof_completeness` "
        f"on {timestamp}. Do not edit by hand._"
    )
    out.append("")
    out.append("## Overview")
    out.append("")
    n_total = int(meta.get("n_parameters", len(rows)))
    out.append(
        f"- **Parameters audited:** {n_total}"
    )
    out.append(
        f"- **Bayesian scan:** Gaussian prior, "
        f"σ = {meta.get('sigma_fraction', 0.01)*100:.2f} % of |value|, "
        f"{meta.get('n_samples', 1000)} samples."
    )
    out.append("")
    out.append("### Status histogram")
    out.append("")
    out.append("| Status | Count |")
    out.append("| --- | ---: |")
    for bucket in STATUS_ORDER:
        out.append(
            f"| {STATUS_PRETTY.get(bucket, bucket)} | "
            f"{status_counts.get(bucket, 0)} |"
        )
    out.append("")

    out.append("## Per-section ledger")
    out.append("")

    # Group rows by section deterministically (alphabetical), but pin
    # '(none)' last so prefix-less params don't sit above 'algebra'.
    sections = sorted(per_section.keys(), key=lambda s: (s == "(none)", s))

    rows_by_section: Dict[str, List[Dict[str, Any]]] = {}
    for r in rows:
        rows_by_section.setdefault(r.get("section", "(none)"), []).append(r)

    for section in sections:
        section_rows = sorted(
            rows_by_section.get(section, []),
            key=lambda r: r.get("parameter", ""),
        )
        if not section_rows:
            continue
        out.append(f"### {section}")
        out.append("")
        counts = per_section.get(section, {})
        counts_str = ", ".join(
            f"{STATUS_PRETTY.get(b, b)}: {counts.get(b, 0)}"
            for b in STATUS_ORDER if counts.get(b, 0) > 0
        )
        if counts_str:
            out.append(f"_{counts_str}_")
            out.append("")
        out.append(
            "| Parameter | Value | Status | EML Tree | Uncertainty "
            "| Duplicate Derivations |"
        )
        out.append("| --- | --- | --- | --- | ---: | --- |")
        for r in section_rows:
            out.append(
                "| {p} | {v} | {s} | {e} | {u} | {d} |".format(
                    p=str(r.get("parameter", "")).replace("|", "\\|"),
                    v=_fmt_value(r.get("value")),
                    s=STATUS_PRETTY.get(str(r.get("status", "")), str(r.get("status", ""))),
                    e=_fmt_eml(r.get("eml_tree")),
                    u=_fmt_uncertainty(r.get("uncertainty")),
                    d=_fmt_duplicates(r.get("duplicate_derivations")),
                )
            )
        out.append("")

    out.append("---")
    out.append("")
    out.append(
        "Classifier version: "
        f"`{meta.get('classifier_version', 'sprint5.task7.v1')}`."
    )
    out.append("")
    return "\n".join(out)


def main() -> int:
    """Build and persist the proof-completeness ledger.

    Returns
    -------
    int
        ``0`` on success — even when ``parameters.json`` is absent the
        function emits an empty ledger and exits clean so the build
        pipeline doesn't stall on a missing prerequisite.
    """
    ag = autogen_dir()
    registry = _load_registry_from_parameters_json()

    ledger = ProofLedger().derive_proof_ledger(registry)

    # Inject the build-time metadata onto the ledger payload.
    timestamp = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    ledger.setdefault("meta", {})
    ledger["meta"]["generated_at"] = timestamp
    ledger["meta"]["source_file"] = PARAMETERS_FILENAME
    ledger["meta"]["framework"] = "Principia Metaphysica"
    ledger["meta"]["sprint"] = "Sprint 5 task #7"

    # --- JSON ---
    json_path = ag / LEDGER_JSON_NAME
    json_path.write_text(
        json.dumps(ledger, indent=2, sort_keys=False),
        encoding="utf-8",
    )

    # --- Markdown ---
    md_text = _render_markdown(ledger, timestamp=timestamp)
    md_path = ag / LEDGER_MD_NAME
    md_path.write_text(md_text, encoding="utf-8")

    counts = ledger.get("status_counts", {})
    print("proof_completeness ledger:")
    print(f"  total parameters: {ledger['meta']['n_parameters']}")
    for bucket in STATUS_ORDER:
        print(f"    {bucket:22s}: {counts.get(bucket, 0)}")
    print(f"  -> {json_path}")
    print(f"  -> {md_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
